 79: class ControlCenterHandler(BaseHTTPRequestHandler):
 80:     controller: ProductController
 81:     server_version = "MultipleAutomation/1"
 82: 
 83:     def log_message(self, format: str, *args: object) -> None:
 84:         # Deliberately suppress request logging; POST bodies may carry transient proxy material.
 85:         return
 86: 
 87:     def _trusted_host(self) -> bool:
 88:         host = self.headers.get("Host", "").split(":", 1)[0].strip("[]").lower()
 89:         return host in {"127.0.0.1", "localhost", "::1"}
 90: 
 91:     def _json(self, status: int, payload: Any) -> None:
 92:         body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
 93:         self.send_response(status)
 94:         self.send_header("Content-Type", "application/json; charset=utf-8")
 95:         self.send_header("Content-Length", str(len(body)))
 96:         self.send_header("Cache-Control", "no-store")
 97:         self.end_headers()
 98:         self.wfile.write(body)
 99: 
100:     def _body(self) -> dict[str, Any]:
101:         length = int(self.headers.get("Content-Length", "0") or "0")
102:         if length > 64 * 1024:
103:             raise ValueError("request body too large")
104:         raw = self.rfile.read(length) if length else b"{}"
105:         value = json.loads(raw.decode("utf-8"))
106:         if not isinstance(value, dict):
107:             raise ValueError("JSON body must be an object")
108:         return value
109: 
110:     def do_GET(self) -> None:
111:         if not self._trusted_host():
112:             self._json(HTTPStatus.FORBIDDEN, {"error": "untrusted Host header"})
113:             return
114:         path = urlparse(self.path).path
115:         try:
116:             if path == "/":
117:                 body = PAGE.encode("utf-8")
118:                 self.send_response(HTTPStatus.OK)
119:                 self.send_header("Content-Type", "text/html; charset=utf-8")
120:                 self.send_header("Content-Length", str(len(body)))
121:                 self.send_header("Cache-Control", "no-store")
122:                 self.end_headers()
123:                 self.wfile.write(body)
124:                 return
125:             if path == "/api/gpm/groups":
126:                 self._json(HTTPStatus.OK, self.controller.list_gpm_groups())
127:                 return
128:             if path == "/api/channel-packs":
129:                 self._json(HTTPStatus.OK, self.controller.list_channel_packs())
130:                 return
131:             if path == "/api/workspaces":
132:                 self._json(HTTPStatus.OK, self.controller.list_workspaces())
133:                 return
134:             if path.startswith("/api/workspaces/"):
135:                 tail = path.removeprefix("/api/workspaces/")
136:                 workspace_id, _, action = tail.partition("/")
137:                 if action == "content/packages":
138:                     self._json(HTTPStatus.OK, self.controller.discover_content_packages(workspace_id))
139:                     return
140:                 if not action:
141:                     self._json(HTTPStatus.OK, self.controller.workspace_overview(workspace_id))
142:                     return
143:                 self._json(HTTPStatus.NOT_FOUND, {"error": "not found"})
144:                 return
145:             self._json(HTTPStatus.NOT_FOUND, {"error": "not found"})
146:         except Exception as exc:
147:             self._json(HTTPStatus.BAD_REQUEST, {"error": self._safe_error(exc)})
148: 
149:     def do_POST(self) -> None:
150:         if not self._trusted_host():
151:             self._json(HTTPStatus.FORBIDDEN, {"error": "untrusted Host header"})
152:             return
153:         path = urlparse(self.path).path
154:         try:
155:             body = self._body()
156:             if path == "/api/workspaces":
157:                 self._json(HTTPStatus.CREATED, self.controller.create_workspace(content_root=body.get("content_root")))
158:                 return
159:             prefix = "/api/workspaces/"
160:             if not path.startswith(prefix):
161:                 self._json(HTTPStatus.NOT_FOUND, {"error": "not found"})
162:                 return
163:             tail = path[len(prefix):]
164:             workspace_id, _, action = tail.partition("/")
165:             routes = {
166:                 "setup/reconcile": lambda: self.controller.reconcile_identity_setup(workspace_id),
167:                 "setup": lambda: self.controller.setup_identity(workspace_id, **{
168:                     "email": str(body.get("email") or ""),
169:                     "credential_ref": str(body.get("credential_ref") or "").strip() or None,
170:                     "proxy_material": str(body.get("proxy_material") or ""),
171:                     "gpm_group_id": str(body.get("gpm_group_id") or "").strip() or None,
172:                     "channel_pack_id": str(body.get("channel_pack_id") or "").strip() or None,
173:                     "google_password": str(body.get("google_password") or ""),
174:                     "google_totp_secret": str(body.get("google_totp_secret") or ""),
175:                 }),
176:                 "credentials": lambda: self.controller.save_google_credentials(
177:                     workspace_id,
178:                     password=str(body.get("password") or ""),
179:                     totp_secret=str(body.get("totp_secret") or ""),
180:                 ),
181:                 "channel-pack/select": lambda: self.controller.select_channel_pack(
182:                     workspace_id,
183:                     str(body.get("pack_id") or ""),
184:                 ),
185:                 "channel-pack/selected": lambda: self.controller.apply_selected_channel_pack(workspace_id),
186:                 "channel-pack/description-recover": lambda: self.controller.recover_approved_channel_description(
187:                     workspace_id,
188:                     str(body.get("predecessor_effect_id") or ""),
189:                     str(body.get("approved_description_digest") or ""),
190:                 ),
191:                 "channel-pack/avatar-recover": lambda: self.controller.recover_approved_channel_avatar(
192:                     workspace_id,
193:                     str(body.get("predecessor_effect_id") or ""),
194:                     str(body.get("approved_avatar_digest") or ""),
195:                 ),
196:                 "browser/start": lambda: self.controller.start_browser(workspace_id),
197:                 "channel": lambda: self.controller.inspect_channel(workspace_id),
198:                 "channel/select": lambda: self.controller.select_channel(
199:                     workspace_id,
200:                     str(body.get("remote_channel_id") or ""),
201:                 ),
202:                 "channel-pack": lambda: self.controller.apply_channel_pack(workspace_id, str(body.get("pack_path") or "")),
203:                 "eligibility": lambda: self.controller.inspect_eligibility(workspace_id),
204:                 "eligibility/verify": lambda: self.controller.ensure_eligibility(
205:                     workspace_id, str(body.get("client_intent_id") or "") or None),
206:                 "content-root": lambda: self.controller.set_content_root(
207:                     workspace_id,
208:                     str(body.get("content_root") or ""),
209:                 ),
210:                 "content/seal": lambda: self.controller.seal_discovered_content(
211:                     workspace_id,
212:                     str(body.get("package_ref") or ""),
213:                 ),
214:                 "publish/review": lambda: self.controller.publish_review(workspace_id),
215:                 "publish": lambda: self.controller.publish_private(
216:                     workspace_id,
217:                     str(body.get("review_digest") or ""),
218:                     str(body.get("client_intent_id") or "") or None,
219:                 ),
220:             }
221:             if action not in routes:
222:                 self._json(HTTPStatus.NOT_FOUND, {"error": "not found"})
223:                 return
224:             self._json(HTTPStatus.OK, routes[action]())
225:         except (ValueError, json.JSONDecodeError, ProductStateError, RuntimeError) as exc:
226:             self._json(HTTPStatus.BAD_REQUEST, {"error": self._safe_error(exc)})
227:         except Exception:
228:             self._json(HTTPStatus.INTERNAL_SERVER_ERROR, {"error": "unexpected local control error"})
229: 
230:     @staticmethod
231:     def _safe_error(exc: Exception) -> str:
232:         text = str(exc).strip()
233:         # Product exceptions are designed to be secret-free; bound length prevents accidental dumps.
234:         return (text or exc.__class__.__name__)[:300]
