237: def serve(*, data_root: str | Path, host: str = "127.0.0.1", port: int = 8787) -> None:
238:     if host not in {"127.0.0.1", "::1", "localhost"}:
239:         raise ValueError("V1 control center may bind only to loopback")
240:     root = Path(data_root).resolve()
241:     store = SQLiteProductStore(root / "multiple-automation.sqlite3")
242:     controller = ProductController(store, data_root=root)
243:     handler = type("BoundControlCenterHandler", (ControlCenterHandler,), {"controller": controller})
244:     server = ThreadingHTTPServer((host, port), handler)
245:     print(f"Multiple Automation: http://{host}:{server.server_port}")
246:     server.serve_forever()
